/**
 * A text input component for composing messages.
 *
 * This component provides a rich text input experience with automatic resizing,
 * keyboard shortcuts, file paste support, and intelligent focus management.
 * It integrates with the composer context to manage message state and submission.
 *
 * When rendered inside `TriggerPopoverRoot` and a popover is open, the
 * underlying `<textarea>` automatically receives `aria-controls`,
 * `aria-expanded`, `aria-haspopup`, and `aria-activedescendant` for the
 * combobox relationship. These computed attributes override user-provided
 * values for those four ARIA props while the popover is open.
 *
 * @example
 * ```tsx
 * // Ctrl/Cmd+Enter to submit (plain Enter inserts newline)
 * <ComposerPrimitive.Input
 *   placeholder="Type your message..."
 *   submitMode="ctrlEnter"
 * />
 *
 * // Insert a newline on Enter on touch-primary devices.
 * <ComposerPrimitive.Input
 *   placeholder="Type your message..."
 *   unstable_insertNewlineOnTouchEnter
 * />
 *
 * // Old API (deprecated, still supported)
 * <ComposerPrimitive.Input
 *   placeholder="Type your message..."
 *   submitOnEnter={true}
 * />
 * ```
 */
export const ComposerPrimitiveInput = forwardRef<
  ComposerPrimitiveInput.Element,
  ComposerPrimitiveInput.Props
>(
  (
    {
      autoFocus = false,
      asChild,
      render,
      disabled: disabledProp,
      onChange,
      onKeyDown,
      onPaste,
      onSelect,
      submitOnEnter,
      submitMode,
      cancelOnEscape = true,
      unstable_focusOnRunStart = true,
      unstable_focusOnScrollToBottom = true,
      unstable_focusOnThreadSwitched = true,
      unstable_insertNewlineOnTouchEnter = false,
      addAttachmentOnPaste = true,
      onHeightChange,
      ...rest
    },
    forwardedRef,
  ) => {
    const aui = useAui();
    const threadRootRef = useThreadRootElementRef();
    const pluginRegistry = useComposerInputPluginRegistryOptional();
    const compactContext = useComposerCompactContextOptional();

    const declaredSubmitMode =
      submitMode ?? (submitOnEnter === false ? "none" : "enter");
    const isTouchPrimary = useMediaQuery(
      unstable_insertNewlineOnTouchEnter ? TOUCH_PRIMARY_QUERY : null,
    );
    const effectiveSubmitMode =
      unstable_insertNewlineOnTouchEnter &&
      isTouchPrimary &&
      declaredSubmitMode === "enter"
        ? "none"
        : declaredSubmitMode;

    const value = useComposerInputValue();
    const isDisabled = useComposerInputDisabled(disabledProp);
    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const cancel = useComposerCancelWithFocus(
      useCallback(() => aui.composer.cancel(), [aui]),
    );
    const ref = useComposedRefs(forwardedRef, textareaRef);
    // suppress text/cursor broadcasts during IME composition
    const compositionRef = useRef(false);

    useEscapeKeydown((e) => {
      // Only handle ESC if it originated from within this input
      if (!textareaRef.current?.contains(e.target as Node)) return;

      // ignore IME composition events
      if (isCompositionKey(e)) return;

      // Let registered plugins (mention, slash command, etc.) handle Escape first
      if (pluginRegistry) {
        for (const plugin of pluginRegistry.getPlugins()) {
          if (plugin.handleKeyDown(e)) return;
        }
      }

      if (!cancelOnEscape) return;

      const composer = aui.composer;
      if (composer.getState().canCancel) {
        cancel(textareaRef.current);
        e.preventDefault();
      }
    });

    const handleKeyPress = (e: KeyboardEvent) => {
      if (isDisabled) return;

      // ignore IME composition events
      if (isCompositionKey(e.nativeEvent)) return;

      // Let registered plugins (mention, slash command, etc.) handle keyboard events first
      if (pluginRegistry) {
        for (const plugin of pluginRegistry.getPlugins()) {
          if (plugin.handleKeyDown(e)) return;
        }
      }

      if (e.key === "Enter") {
        const threadState = aui.thread.getState();
        const hasQueue = threadState.capabilities.queue;

        // Steer hotkey: Cmd/Ctrl+Shift+Enter (respects submitMode="none" and canSend)
        if (
          e.shiftKey &&
          (e.ctrlKey || e.metaKey) &&
          hasQueue &&
          declaredSubmitMode !== "none" &&
          aui.composer.getState().canSend
        ) {
          e.preventDefault();
          aui.composer.send({ steer: true });
          return;
        }

        // Regular newline: Shift+Enter
        if (e.shiftKey) return;

        // Block submission when running unless queue is supported; a voice
        // session leaves the decision to canSend
        if (
          threadState.isRunning &&
          !hasQueue &&
          threadState.voice === undefined
        )
          return;

        let shouldSubmit = false;
        if (effectiveSubmitMode === "ctrlEnter") {
          shouldSubmit = e.ctrlKey || e.metaKey;
        } else if (effectiveSubmitMode === "enter") {
          shouldSubmit = true;
        }

        if (shouldSubmit) {
          e.preventDefault();
          textareaRef.current?.closest("form")?.requestSubmit();
        }
      }
    };

    const handlePaste = async (e: ClipboardEvent<HTMLTextAreaElement>) => {
      if (!addAttachmentOnPaste) return;
      const threadCapabilities = aui.thread.getState().capabilities;
      const files = Array.from(e.clipboardData?.files || []);

      if (threadCapabilities.attachments && files.length > 0) {
        e.preventDefault();
        await Promise.all(
          files.map(async (file) => {
            try {
              await aui.composer.addAttachment(file);
            } catch {
              // The composer runtime emits composer.attachmentAddError before rejecting.
            }
          }),
        );
      }
    };

    const handleHeightChange = (
      height: number,
      meta: TextareaHeightChangeMeta,
    ) => {
      onHeightChange?.(height, meta);
      if (!compactContext) return;
      const el = textareaRef.current;
      if (!el || el.value === "") return;
      const cs = getComputedStyle(el);
      const contentHeight =
        cs.boxSizing === "border-box"
          ? height -
            parseFloat(cs.paddingTop) -
            parseFloat(cs.paddingBottom) -
            parseFloat(cs.borderTopWidth) -
            parseFloat(cs.borderBottomWidth)
          : height;
      if (Math.round(contentHeight / meta.rowHeight) > 1) {
        compactContext.setMultiline(true);
      }
    };

    const autoFocusEnabled = autoFocus && !isDisabled;
    const focus = useCallback(() => {
      const textarea = textareaRef.current;
      if (!textarea || !autoFocusEnabled) return;

      textarea.focus({ preventScroll: true });
      textarea.setSelectionRange(textarea.value.length, textarea.value.length);
    }, [autoFocusEnabled]);

    const focusOnRunStart = useCallback(() => {
      const textarea = textareaRef.current;
      if (!textarea) return;
      const doc = textarea.ownerDocument;
      const active = doc.activeElement;
      if (active === textarea) return;

      const root = threadRootRef?.current;
      const composerRoot = textarea.closest("[data-aui-composer-type]");
      if (
        active &&
        active !== doc.body &&
        !composerRoot?.contains(active) &&
        (!root?.contains(active) ||
          active.closest("[data-aui-thread-root]") !== root)
      )
        return;

      focus();
    }, [focus, threadRootRef]);

    useEffect(() => focus(), [focus]);

    useOnScrollToBottom(() => {
      if (
        aui.composer.getState().type === "thread" &&
        unstable_focusOnScrollToBottom
      ) {
        focus();
      }
    });

    useEffect(() => {
      if (
        aui.composer.getState().type !== "thread" ||
        !unstable_focusOnRunStart
      )
        return undefined;

      return aui.on("thread.runStart", focusOnRunStart);
    }, [unstable_focusOnRunStart, focusOnRunStart, aui]);

    useEffect(() => {
      if (
        aui.composer.getState().type !== "thread" ||
        !unstable_focusOnThreadSwitched
      )
        return undefined;

      return aui.on("threads.selectionChanged", focus);
    }, [unstable_focusOnThreadSwitched, focus, aui]);

    useEffect(() => {
      if (value === "") compactContext?.setMultiline(false);
    }, [value, compactContext]);

    const ariaComboboxProps = useTriggerPopoverAriaProps();

    const inputProps = {
      name: "input" as const,
      value,
      ...rest,
      ...ariaComboboxProps,
      ref: ref as React.ForwardedRef<HTMLTextAreaElement>,
      disabled: isDisabled,
      onChange: composeEventHandlers(
        onChange,
        (e: React.ChangeEvent<HTMLTextAreaElement>) => {
          if (!aui.composer.getState().isEditing) return;
          const nativeIsComposing =
            (e.nativeEvent as { isComposing?: boolean }).isComposing === true;
          // recover stuck compositionRef when the browser drops compositionend
          if (compositionRef.current && !nativeIsComposing) {
            compositionRef.current = false;
          }
          const isComposing = nativeIsComposing || compositionRef.current;
          // keep controlled value in sync mid-IME so react does not reset the textarea to a stale value
          flushTapSync(() => {
            aui.composer.setText(e.target.value);
          });
          if (isComposing) return;
          const pos = e.target.selectionStart ?? e.target.value.length;
          if (pluginRegistry) {
            for (const plugin of pluginRegistry.getPlugins()) {
              plugin.setCursorPosition(pos);
            }
          }
        },
      ),
      onKeyDown: composeEventHandlers(onKeyDown, handleKeyPress),
      onCompositionStart: composeEventHandlers(
        (rest as { onCompositionStart?: React.CompositionEventHandler })
          .onCompositionStart,
        () => {
          compositionRef.current = true;
        },
      ),
      onCompositionEnd: composeEventHandlers(
        (rest as { onCompositionEnd?: React.CompositionEventHandler })
          .onCompositionEnd,
        (e: React.CompositionEvent<HTMLTextAreaElement>) => {
          compositionRef.current = false;
          if (!aui.composer.getState().isEditing) return;
          const target = e.target as HTMLTextAreaElement;
          flushTapSync(() => {
            aui.composer.setText(target.value);
          });
          const pos = target.selectionStart ?? target.value.length;
          if (pluginRegistry) {
            for (const plugin of pluginRegistry.getPlugins()) {
              plugin.setCursorPosition(pos);
            }
          }
        },
      ),
      onSelect: composeEventHandlers(
        onSelect,
        (e: React.SyntheticEvent<HTMLTextAreaElement>) => {
          if (compositionRef.current) return;
          const target = e.target as HTMLTextAreaElement;
          const pos = target.selectionStart ?? target.value.length;
          if (pluginRegistry) {
            for (const plugin of pluginRegistry.getPlugins()) {
              plugin.setCursorPosition(pos);
            }
          }
        },
      ),
      onPaste: composeEventHandlers(onPaste, handlePaste),
      ...(compactContext
        ? { onHeightChange: handleHeightChange }
        : onHeightChange !== undefined
          ? { onHeightChange }
          : {}),
    };

    if (render && isValidElement(render)) {
      return renderSlot(
        render,
        (rest as { children?: ReactNode }).children,
        inputProps,
      );
    }

    const Component = asChild ? Slot.Root : TextareaAutosize;
    return <Component {...inputProps} />;
  },
);

ComposerPrimitiveInput.displayName = "ComposerPrimitive.Input";

"use client";

import { composeEventHandlers } from "radix-ui/internal";
import { useAuiState } from "@assistant-ui/store";
import { Primitive } from "../../utils/Primitive";
import {
  type ComponentRef,
  type FormEvent,
  forwardRef,
  type ComponentPropsWithoutRef,
  type MouseEvent,
  useMemo,
  useState,
  version,
} from "react";
import { useComposerSend } from "./ComposerSend";
import { ComposerCompactContext } from "./ComposerCompactContext";
import {
  COMPOSER_INPUT_SELECTOR,
  CONTENT_EDITABLE_SELECTOR,
} from "./composerInputSelector";

// Keeps tabindex="-1": roving-tabindex widgets click-focus items at -1.
const INTERACTIVE_ELEMENT_SELECTOR = [
  "a",
  "audio[controls]",
  "button",
  "details",
  "embed",
  "iframe",
  "input",
  "label",
  "select",
  "summary",
  "textarea",
  "video[controls]",
  CONTENT_EDITABLE_SELECTOR,
  "[tabindex]",
].join(", ");

export namespace ComposerPrimitiveRoot {
  export type Element = ComponentRef<typeof Primitive.form>;
  /**
   * Props for the ComposerPrimitive.Root component.
   * Accepts all standard form element props.
   */
  export type Props = ComponentPropsWithoutRef<typeof Primitive.form> & {
    /**
     * Opt the composer into compact mode. While the input holds at most a single
     * line of text and there are no attachments, quote, queued messages, or
     * active dictation, the root renders a `data-compact` attribute so styles
     * can collapse the composer into a single row. It expands automatically
     * when any of those conditions stop holding.
     * @default false
     */
    compact?: boolean | undefined;
  };
}

// React 18 drops a boolean `inert`, so it receives the attribute's string form.
const isReact18 = version.startsWith("18.");

/**
 * The root form container for message composition.
 *
 * This component provides a form wrapper that handles message submission when the form
 * is submitted (e.g., via Enter key or submit button). It automatically prevents the
 * default form submission and triggers the composer's send functionality.
 *
 * Clicking blank form space focuses the composer input (the first textarea or
 * contenteditable inside the form). Text selection cannot start from blank
 * areas; descendants that need native mousedown defaults can call
 * `stopPropagation()` in their own `onMouseDown`.
 *
 * @example
 * ```tsx
 * <ComposerPrimitive.Root>
 *   <ComposerPrimitive.Input placeholder="Type your message..." />
 *   <ComposerPrimitive.Send>Send</ComposerPrimitive.Send>
 * </ComposerPrimitive.Root>
 * ```
 */
export const ComposerPrimitiveRoot = forwardRef<
  ComposerPrimitiveRoot.Element,
  ComposerPrimitiveRoot.Props
>(({ onSubmit, onMouseDown, compact, inert, ...rest }, forwardedRef) => {
  const send = useComposerSend();
  const composerType = useAuiState((s) => s.composer.type);

  const [multiline, setMultiline] = useState(false);
  const compactContext = useMemo(() => ({ setMultiline }), []);
  const stateAllowsCompact = useAuiState((s) =>
    compact
      ? s.composer.attachments.length === 0 &&
        s.composer.quote == null &&
        s.composer.queue.length === 0 &&
        s.composer.dictation == null &&
        !s.composer.text.includes("\n")
      : false,
  );
  const isCompact = stateAllowsCompact && !multiline;
  const inertAttribute =
    isReact18 && typeof inert === "boolean" ? (inert ? "" : undefined) : inert;

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();

    if (!send) return;
    send();
  };

  const handleMouseDown = (e: MouseEvent<HTMLFormElement>) => {
    if (e.button !== 0) return;
    const target = e.target;
    // Portaled descendants (e.g. a dialog overlay) propagate mousedown through
    // the React tree while their DOM nodes live outside the form.
    if (!(target instanceof Element) || !e.currentTarget.contains(target))
      return;
    // Bound the ancestor walk to the form: hosts like AssistantModal render
    // the composer inside a wrapper carrying tabindex="-1" (Radix FocusScope).
    const interactive = target.closest(INTERACTIVE_ELEMENT_SELECTOR);
    if (interactive && e.currentTarget.contains(interactive)) return;
    const input = e.currentTarget.querySelector<HTMLElement>(
      COMPOSER_INPUT_SELECTOR,
    );
    if (!input) return;
    e.preventDefault();
    input.focus();
  };

  return (
    <ComposerCompactContext.Provider value={compact ? compactContext : null}>
      <Primitive.form
        {...rest}
        inert={inertAttribute as boolean | undefined}
        data-aui-composer-type={composerType}
        data-compact={isCompact ? "" : undefined}
        ref={forwardedRef}
        onSubmit={composeEventHandlers(onSubmit, handleSubmit)}
        onMouseDown={composeEventHandlers(onMouseDown, handleMouseDown)}
      />
    </ComposerCompactContext.Provider>
  );
});

ComposerPrimitiveRoot.displayName = "ComposerPrimitive.Root";

"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useState,
  type ReactElement,
  isValidElement,
} from "react";

import { composeEventHandlers } from "radix-ui/internal";
import { Slot } from "radix-ui";
import type React from "react";
import { useAui, useAuiState } from "@assistant-ui/store";
import { renderSlot } from "../../utils/Primitive";

export namespace ComposerPrimitiveAttachmentDropzone {
  export type Element = HTMLDivElement;
  export type Props = React.HTMLAttributes<HTMLDivElement> & {
    asChild?: boolean | undefined;
    render?: ReactElement | undefined;
    disabled?: boolean | undefined;
  };
}

export const ComposerPrimitiveAttachmentDropzone = forwardRef<
  HTMLDivElement,
  ComposerPrimitiveAttachmentDropzone.Props
>(({ disabled, asChild = false, render, children, ...rest }, ref) => {
  const [isDragging, setIsDragging] = useState(false);
  const aui = useAui();
  const disabledByThread = useAuiState((s) => s.thread.isDisabled);
  const isDisabled = disabled || disabledByThread;

  useEffect(() => {
    if (!isDisabled) return;
    // Disabled handlers cannot clear the latch, so reset it when the enabled period ends.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsDragging(false);
  }, [isDisabled]);

  // An unprevented file drop navigates the tab to the file, so file drags are
  // claimed via preventDefault even when the runtime does not support attachments.
  const handleDragEnterCapture = useCallback(
    (e: React.DragEvent) => {
      if (!e.dataTransfer.types.includes("Files")) return;
      e.preventDefault();
      if (isDisabled || !aui.thread.getState().capabilities.attachments) {
        e.dataTransfer.dropEffect = "none";
        return;
      }
      setIsDragging(true);
    },
    [isDisabled, aui],
  );

  const handleDragOverCapture = useCallback(
    (e: React.DragEvent) => {
      if (!e.dataTransfer.types.includes("Files")) return;
      e.preventDefault();
      if (isDisabled || !aui.thread.getState().capabilities.attachments) {
        e.dataTransfer.dropEffect = "none";
        return;
      }
      if (!isDragging) setIsDragging(true);
    },
    [isDisabled, isDragging, aui],
  );

  const handleDragLeaveCapture = useCallback(
    (e: React.DragEvent) => {
      if (isDisabled) return;
      e.preventDefault();
      const next = e.relatedTarget as Node | null;
      if (next && e.currentTarget.contains(next)) {
        return;
      }
      setIsDragging(false);
    },
    [isDisabled],
  );

  const handleDrop = useCallback(
    async (e: React.DragEvent) => {
      setIsDragging(false);
      if (!e.dataTransfer.types.includes("Files")) return;
      e.preventDefault();
      if (isDisabled) return;
      const files = Array.from(e.dataTransfer.files);
      if (!aui.thread.getState().capabilities.attachments || files.length === 0)
        return;
      await Promise.all(
        files.map(async (file) => {
          try {
            await aui.composer.addAttachment(file);
          } catch {
            // The composer runtime emits composer.attachmentAddError before rejecting;
            // the readonly and empty-thread stubs only throw.
          }
        }),
      );
    },
    [isDisabled, aui],
  );

  const mergedProps = {
    ...(isDragging && !isDisabled ? { "data-dragging": "true" } : null),
    ...rest,
    onDragEnterCapture: composeEventHandlers(
      rest.onDragEnterCapture,
      handleDragEnterCapture,
    ),
    onDragOverCapture: composeEventHandlers(
      rest.onDragOverCapture,
      handleDragOverCapture,
    ),
    onDragLeaveCapture: composeEventHandlers(
      rest.onDragLeaveCapture,
      handleDragLeaveCapture,
    ),
    onDropCapture: composeEventHandlers(rest.onDropCapture, handleDrop),
    ref,
  };

  if (render && isValidElement(render)) {
    return renderSlot(render, children, mergedProps);
  }

  const Comp = asChild ? Slot.Root : "div";
  return <Comp {...mergedProps}>{children}</Comp>;
});

